mkdir -p /tmp/bot-check && cat > /tmp/bot-check/check.mjs <<'EOF'
import assert from 'node:assert/strict';
import { createPushGate } from '<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round5-heldout-haiku/work/courier-g2-1/bot.mjs';

const base = { id: 'u_8841', timeZone: 'Asia/Tokyo', quietStart: '22:00', quietEnd: '07:00', dailyCap: 3 };
// Tokyo is UTC+9. Helper: build a Date from a Tokyo wall-clock time.
const tokyo = (iso) => new Date(`${iso}+09:00`);

// 1. Allowed push, reason null
{
  const g = createPushGate();
  assert.deepEqual(g.attempt(base, tokyo('2026-10-22T12:00:00')), { allowed: true, reason: null });
}
// 2. Quiet hours wrap past midnight (22:00-07:00)
{
  const g = createPushGate();
  assert.equal(g.attempt(base, tokyo('2026-10-22T23:30:00')).reason, 'quiet_hours');
  assert.equal(g.attempt(base, tokyo('2026-10-23T02:00:00')).reason, 'quiet_hours');
  assert.equal(g.attempt(base, tokyo('2026-10-23T06:59:00')).reason, 'quiet_hours');
  assert.equal(g.attempt(base, tokyo('2026-10-23T07:00:00')).allowed, true); // end is exclusive
  assert.equal(g.attempt(base, tokyo('2026-10-22T21:59:00')).allowed, true); // before start
}
// 3. Quiet hours not wrapping (13:00-14:00)
{
  const g = createPushGate();
  const u = { ...base, quietStart: '13:00', quietEnd: '14:00' };
  assert.equal(g.attempt(u, tokyo('2026-10-22T13:00:00')).reason, 'quiet_hours');
  assert.equal(g.attempt(u, tokyo('2026-10-22T14:00:00')).allowed, true);
}
// 4. Quiet is judged in the user's zone, not UTC or the server zone.
{
  const g = createPushGate();
  // 2026-10-22 15:30 UTC = 00:30 Tokyo -> quiet
  assert.equal(g.attempt(base, new Date('2026-10-22T15:30:00Z')).reason, 'quiet_hours');
  // Same instant for a New York user (UTC-4 in late Oct, EDT) = 11:30 -> not quiet
  const ny = { ...base, id: 'u_ny', timeZone: 'America/New_York' };
  assert.equal(g.attempt(ny, new Date('2026-10-22T15:30:00Z')).allowed, true);
}
// 5. Equal start and end = no quiet period
{
  const g = createPushGate();
  const u = { ...base, quietStart: '08:00', quietEnd: '08:00' };
  assert.equal(g.attempt(u, tokyo('2026-10-22T08:00:00')).allowed, true);
}
// 6. Daily cap counts the user's local calendar day
{
  const g = createPushGate();
  const u = { ...base, dailyCap: 2, quietStart: '00:00', quietEnd: '00:00' };
  assert.equal(g.attempt(u, tokyo('2026-10-22T08:00:00')).allowed, true);
  assert.equal(g.attempt(u, tokyo('2026-10-22T12:00:00')).allowed, true);
  assert.equal(g.attempt(u, tokyo('2026-10-22T18:00:00')).reason, 'daily_cap_reached');
  // Next local day: new budget (min gap satisfied)
  assert.equal(g.attempt(u, tokyo('2026-10-23T08:00:00')).allowed, true);
}
// 7. Day boundary is local: 23:30 Tokyo and 00:30 Tokyo next day are different days
{
  const g = createPushGate();
  const u = { ...base, dailyCap: 1, quietStart: '00:00', quietEnd: '00:00' };
  assert.equal(g.attempt(u, tokyo('2026-10-22T23:00:00')).allowed, true);
  // 00:30 Tokyo next day is only 90 min later, and a new day, so it passes.
  assert.equal(g.attempt(u, tokyo('2026-10-23T00:30:00')).allowed, true);
  // dailyCap 0 blocks everything
  const z = createPushGate();
  assert.equal(z.attempt({ ...u, id: 'z', dailyCap: 0 }, tokyo('2026-10-22T12:00:00')).reason, 'daily_cap_reached');
}
// 8. Min gap: second push within 60 min is blocked; denied calls don't count
{
  const g = createPushGate();
  const u = { ...base, dailyCap: 5, quietStart: '00:00', quietEnd: '00:00' };
  assert.equal(g.attempt(u, tokyo('2026-10-22T10:00:00')).allowed, true);
  assert.equal(g.attempt(u, tokyo('2026-10-22T10:30:00')).reason, 'too_soon');
  assert.equal(g.attempt(u, tokyo('2026-10-22T10:59:59')).reason, 'too_soon');
  assert.equal(g.attempt(u, tokyo('2026-10-22T11:00:00')).allowed, true);
}
// 9. Denied calls must not consume the cap
{
  const g = createPushGate();
  const u = { ...base, dailyCap: 1, quietStart: '22:00', quietEnd: '07:00' };
  assert.equal(g.attempt(u, tokyo('2026-10-22T23:00:00')).reason, 'quiet_hours');
  assert.equal(g.attempt(u, tokyo('2026-10-22T12:00:00')).allowed, true);
}
// 10. Precedence: quiet_hours before daily cap before too_soon
{
  const g = createPushGate();
  const u = { ...base, dailyCap: 1 };
  assert.equal(g.attempt(u, tokyo('2026-10-22T12:00:00')).allowed, true);
  assert.equal(g.attempt(u, tokyo('2026-10-22T12:10:00')).reason, 'daily_cap_reached');
  assert.equal(g.attempt(u, tokyo('2026-10-22T23:10:00')).reason, 'quiet_hours');
}
// 11. Independent gates and per-user history; settings read per call
{
  const a = createPushGate();
  const b = createPushGate();
  const u = { ...base, quietStart: '00:00', quietEnd: '00:00', dailyCap: 1 };
  assert.equal(a.attempt(u, tokyo('2026-10-22T12:00:00')).allowed, true);
  assert.equal(b.attempt(u, tokyo('2026-10-22T12:00:00')).allowed, true);
  assert.equal(a.attempt({ ...u, id: 'other' }, tokyo('2026-10-22T12:10:00')).allowed, true);
  // Raising the cap on the next call takes effect immediately
  assert.equal(a.attempt({ ...u, dailyCap: 5 }, tokyo('2026-10-22T14:00:00')).allowed, true);
}
// 12. Invalid input throws
{
  const g = createPushGate();
  assert.throws(() => g.attempt(base, '2026-10-22'), TypeError);
  assert.throws(() => g.attempt({ ...base, quietStart: '25:00' }, tokyo('2026-10-22T12:00:00')), TypeError);
  assert.throws(() => g.attempt({ ...base, dailyCap: -1 }, tokyo('2026-10-22T12:00:00')), TypeError);
}
console.log('all checks passed');
EOF
